      <rect x="130" y="50" width="10" height="10" fill="#4f46e5"/>
      <rect x="90" y="70" width="10" height="10" fill="#4f46e5"/>
      <rect x="10" y="90" width="10" height="10" fill="#4f46e5"/>
      <rect x="30" y="90" width="10" height="10" fill="#4f46e5"/>
